mapper.select:
SELECT 
FROM task WHERE workspace_id = #{workspaceId} AND assigned_to_id = #{userId}
ORDER BY COALESCE(updated_at, created_at) DESC, id DESC LIMIT 25

SELECT 
FROM activity WHERE workspace_id = #{workspaceId} AND created_by_id = #{userId}
ORDER BY timestamp DESC, id DESC LIMIT 25

SELECT DATE(touched_at) AS date, COUNT(*) AS count FROM (
  SELECT timestamp AS touched_at FROM activity
  WHERE workspace_id = #{workspaceId} AND created_by_id = #{userId}
    AND timestamp >= #{from} AND timestamp < #{to}
  UNION ALL
  SELECT updated_at AS touched_at FROM task
  WHERE workspace_id = #{workspaceId} AND assigned_to_id = #{userId} AND completed = TRUE
    AND updated_at >= #{from} AND updated_at < #{to}
) touches GROUP BY DATE(touched_at) ORDER BY date

mapper.sql:
WITH personal AS (
  SELECT p.id FROM person p
  WHERE p.workspace_id = #{workspaceId} AND p.owner_id = #{userId}
    AND p.archived_at IS NULL AND p.suspended_at IS NULL AND p.provision_ceased_at IS NULL
), scores AS (
  SELECT p.id,
    COALESCE(SUM(touch.weight * POW(#{model.decayBase}, -touch.age_days / #{model.halfLifeDays})), 0) AS raw_weight,
    COALESCE(SUM(CASE WHEN touch.age_days <= #{model.recentWindowDays} THEN touch.weight ELSE 0 END), 0) AS recent_weight,
    COALESCE(SUM(CASE WHEN touch.age_days > #{model.recentWindowDays}
      AND touch.age_days <= #{model.priorWindowDays} THEN touch.weight ELSE 0 END), 0) AS prior_weight,
    MAX(touch.touched_at) AS last_touch_at
  FROM personal p LEFT JOIN (
    SELECT source.entity_id, source.touched_at, source.weight,
      TIMESTAMPDIFF(MICROSECOND, source.touched_at, #{reference}) / #{model.microsecondsPerDay} AS age_days
    FROM () source
    JOIN personal owned ON owned.id = source.entity_id
    WHERE source.touched_at IS NOT NULL AND source.touched_at <= #{reference}
  ) touch ON touch.entity_id = p.id GROUP BY p.id
), classified AS (
  SELECT scores.*,
    CASE WHEN raw_weight >= #{model.hotMinimumRawWeight} THEN 'hot'
      WHEN raw_weight >= #{model.warmMinimumRawWeight} THEN 'warm'
      WHEN raw_weight >= #{model.coolMinimumRawWeight} THEN 'cool' ELSE 'cold' END AS band,
    (prior_weight >= #{model.coolingPriorMinimum}
      AND recent_weight < prior_weight * #{model.coolingRecentRatio}
      AND TIMESTAMPDIFF(DAY, last_touch_at, #{reference}) >= #{model.recentWindowDays}) AS cooling
  FROM scores
)
